package com.agacostays.payment.scheduler; import com.agacostays.payment.enums.PaymentStatus; import com.agacostays.payment.repository.PaymentRepository; import org.springframework.beans.factory.annotation.Value; import org.springframework.scheduling.annotation.Scheduled; import org.springframework.stereotype.Component; import java.time.*; import lombok.extern.slf4j.Slf4j;
@Slf4j @Component public class PaymentReconciliationScheduler { private final PaymentRepository payments; private final long age; public PaymentReconciliationScheduler(PaymentRepository p,@Value("${payment.reconciliation.pending-age-minutes:30}")long age){payments=p;this.age=age;} @Scheduled(fixedDelayString="PT10M") public void reconcilePending(){Instant cutoff=Instant.now().minusSeconds(age*60);var pending=payments.findByPaymentStatusAndCreatedAtBefore(PaymentStatus.PENDING,cutoff);for(var p:pending){log.warn("Payment pending beyond reconciliation threshold: paymentId={} gatewayOrderId={}",p.getPaymentId(),p.getGatewayOrderId());}} }
